import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture from asset URL
  const texture = ctx.textureLoader.load(config.assetUrl || '/prism-mock/home/nodes/orb-decor.png');
  texture.colorSpace = THREE.SRGBColorSpace;

  // Plane geometry with 512:320 aspect ratio (1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1);

  // Material for unlit texture display
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    transparent: true,
    side: THREE.DoubleSide,
    toneMapped: false,
  });

  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene position, rotation, and scale from config
  if (config.scenePosition) {
    const { x = 0, y = 0, z = 0, rotationXYZ = [0, 0, 0], scaleXYZ = [1, 1, 1] } = config.scenePosition;
    mesh.position.set(x, y, z);
    mesh.rotation.set(rotationXYZ[0] ?? 0, rotationXYZ[1] ?? 0, rotationXYZ[2] ?? 0);
    mesh.scale.set(scaleXYZ[0] ?? 1, scaleXYZ[1] ?? 1, scaleXYZ[2] ?? 1);
  }

  group.add(mesh);

  // Set up userData with handlers and cleanup
  group.userData = {
    handlers: {},
    cleanup() {
      geometry.dispose();
      material.dispose();
      texture.dispose();
    },
  };

  return group;
}
